    47	export type RegisterInput = z.infer<typeof registerSchema>;
    48	export type PasswordResetRequestInput = z.infer<
    49	  typeof passwordResetRequestSchema
    50	>;
    51	export type PasswordResetConfirmInput = z.infer<
    52	  typeof passwordResetConfirmSchema
    53	>;
