    63	  if (!member || member.status !== "active") return null;
    64	
    65	  const actor: Actor = {
    66	    userId: principal.userId,
    67	    orgId: org.id,
    68	    role: member.role,
    69	  };
    70	
    71	  assertOrgScope(actor, org.id);
