=== src/app/(dashboard)/orgs/page.tsx
     1	/**
     2	 * Org chooser: lists the organizations the signed-in user belongs to and
     3	 * redirects when there is exactly one.
     4	 *
     5	 * Owner D. This is the only route in the dashboard tree without an `[orgSlug]`,
     6	 * so it is also the only one that works with a `SessionPrincipal` instead of an
     7	 * `Actor` — there is no tenant to scope to until the choice is made.
     8	 */
     9	
    10	import Link from "next/link";
    11	import { redirect } from "next/navigation";
    12	import type { Metadata } from "next";
    13	import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
    14	import { getSessionPrincipal } from "@/lib/session";
    15	import { listOrganizationsForUser } from "@/server/services/organization-service";
    16	
    17	type PageParams = Record<string, never>;
    18	
    19	export const dynamic = "force-dynamic";
    20	
    21	export const metadata: Metadata = {
    22	  title: "Choose an organization",
    23	};
    24	
    25	export default async function Page(props: {
    26	  params: Promise<PageParams>;
    27	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    28	}) {
    29	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    30	  await props.params;
    31	  await props.searchParams;
    32	
    33	  const principal = await getSessionPrincipal();
    34	  if (principal === null) {
    35	    throw new UnauthorizedActionError();
    36	  }
    37	
    38	  const organizations = await listOrganizationsForUser(principal.userId);
    39	
    40	  // One organization is the overwhelmingly common case; do not make people
    41	  // click through a list of one.
    42	  if (organizations.length === 1) {
    43	    redirect(`/${organizations[0].slug}`);
    44	  }
    45	
    46	  return (
    47	    <main className="mx-auto max-w-lg px-6 py-20">
    48	      <h1 className="text-xl font-semibold">Choose an organization</h1>
    49	      <p className="mt-2 text-sm text-slate-600">
    50	        Signed in as {principal.email}.
    51	      </p>
    52	
    53	      {organizations.length === 0 ? (
    54	        <p className="mt-8 rounded-md border border-dashed border-slate-300 p-6 text-sm text-slate-600">
    55	          You are not a member of any organization yet. Ask a colleague to invite
    56	          you, or create one of your own.
    57	        </p>
    58	      ) : (
    59	        <ul className="mt-8 space-y-2">
    60	          {organizations.map((org) => (
    61	            <li key={org.id}>
    62	              <Link
    63	                href={`/${org.slug}`}
