    41	/**
    42	 * Reads one flag out of a server-evaluated snapshot, falling back to a live
    43	 * `isEnabled()` evaluation when the snapshot predates the flag.
    44	 */
    45	export function readFlag(
    46	  snapshot: FeatureFlagSnapshot | null,
    47	  flag: FeatureFlagKey,
    48	  context: FlagContext = ANONYMOUS_FLAG_CONTEXT,
    49	): boolean {
